//! tachyon-hostd: the privileged agent on each host. It keeps paused
//! microVMs warm, forks job disks copy-on-write, runs each job in a jailed
//! Cloud Hypervisor VM, and talks to the Go control plane over hostlink.v1.
//!
//! Configuration is by environment variable (see README).

pub mod hypervisor;
pub mod jailer;
pub mod lifecycle;
pub mod link;
pub mod outbox;
pub mod recovery;
pub mod storage;

// Generated by tonic-build; not held to our lint bar.
#[allow(clippy::all, clippy::pedantic)]
pub mod pb {
    tonic::include_proto!("tachyon.hostlink.v1");
}

use anyhow::{Context, Result};
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::atomic::AtomicU32;
use std::sync::Arc;

fn env(key: &str) -> Result<String> {
    std::env::var(key).with_context(|| format!("{key} is required"))
}

fn env_or(key: &str, default: &str) -> String {
    std::env::var(key).unwrap_or_else(|_| default.to_string())
}

/// Parses "2:2,4:2,8:1" (vcpu:count).
fn parse_warm(s: &str) -> Result<HashMap<u32, usize>> {
    let mut m = HashMap::new();
    for part in s.split(',').filter(|p| !p.is_empty()) {
        let (v, n) = part
            .split_once(':')
            .with_context(|| format!("bad warm entry {part:?}"))?;
        m.insert(v.trim().parse()?, n.trim().parse()?);
    }
    Ok(m)
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .json()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env().unwrap_or_else(|_| "info".into()),
        )
        .init();

    if !cfg!(target_os = "linux") {
        anyhow::bail!(
            "tachyon-hostd runs on Linux hosts with KVM; use `cargo test` for development"
        );
    }

    let info = link::HostInfo {
        host_id: env("TACHYON_HOST_ID")?,
        region: env("TACHYON_REGION")?,
        failure_domain: env_or("TACHYON_FAILURE_DOMAIN", "default"),
        arch: env_or("TACHYON_ARCH", "x86_64"),
        vcpu: env("TACHYON_VCPU")?.parse()?,
        memory_gb: env("TACHYON_MEMORY_GB")?.parse()?,
    };
    let hv = hypervisor::CloudHypervisor {
        binary: env_or("TACHYON_CH_BINARY", "/usr/local/bin/cloud-hypervisor").into(),
        ch_remote: env_or("TACHYON_CH_REMOTE", "/usr/local/bin/ch-remote").into(),
        run_dir: env_or("TACHYON_RUN_DIR", "/run/tachyon/vms").into(),
        base_snapshots: PathBuf::from(env("TACHYON_BASE_SNAPSHOTS")?),
        cgroup_parent: env_or("TACHYON_CGROUP", "/sys/fs/cgroup/tachyon").into(),
        base_uid: env_or("TACHYON_BASE_UID", "100000").parse()?,
        next_slot: AtomicU32::new(0),
    };
    let storage = storage::Zfs {
        pool: env("TACHYON_ZFS_POOL")?,
        runner: storage::ExecRunner,
    };
    let warm = parse_warm(&env_or("TACHYON_WARM", "2:2,4:2,8:1"))?;
    let outbox = Arc::new(outbox::Outbox::open(
        env_or("TACHYON_STATE_DIR", "/var/lib/tachyon/hostd").as_ref(),
    )?);

    let agent = Arc::new(lifecycle::Agent::new(hv, storage, warm));
    let mut link = link::Link::new(agent.clone(), info, env("TACHYON_CONTROL_PLANE")?);
    link.outbox = outbox.clone();
    tokio::task::spawn_blocking({
        let (agent, inv) = (agent.clone(), link.inventory.clone());
        move || recover(&agent, &inv, &outbox)
    })
    .await?;
    tokio::task::spawn_blocking(move || agent.refill_pool()).await??;
    tokio::select! {
        _ = link.run() => {}
        _ = tokio::signal::ctrl_c() => tracing::info!("shutting down; the next start reaps running VMs and reports their jobs as infra errors"),
    }
    Ok(())
}

/// Startup recovery (see `recovery`). Each step logs and carries on: a
/// failed cleanup must not keep the host from serving jobs.
fn recover<S: storage::Storage>(
    agent: &lifecycle::Agent<hypervisor::CloudHypervisor, S>,
    inv: &link::Inventory,
    outbox: &outbox::Outbox,
) {
    let lost = recovery::report_interrupted(outbox);
    let vms = recovery::reap_vms(&agent.hv.run_dir, &agent.hv.cgroup_parent);
    let disks = recovery::clean_job_disks(&agent.storage).unwrap_or_else(|e| {
        tracing::warn!(error = %format!("{e:#}"), "clean orphaned job disks");
        Vec::new()
    });
    let snapshots = recovery::rebuild_inventory(&agent.storage, inv).unwrap_or_else(|e| {
        tracing::warn!(error = %format!("{e:#}"), "rebuild snapshot inventory");
        0
    });
    tracing::info!(
        interrupted_jobs = lost.len(),
        orphaned_vms = vms.len(),
        orphaned_disks = disks.len(),
        snapshots,
        unacked = outbox.len(),
        "recovered host state"
    );
}

#[cfg(test)]
mod tests {
    #[test]
    fn parse_warm() {
        let m = super::parse_warm("2:2, 8:1").unwrap();
        assert_eq!(m[&2], 2);
        assert_eq!(m[&8], 1);
        assert!(super::parse_warm("2-2").is_err());
    }
}
